<script>
import moment from "moment";

export default {
    data() {
        return {
            movie: {
                synopsis: "年末解恨！除厄运！保平安！揭露海外犯罪产业黑幕：人口贩卖、器官交易…… 张家辉、阮经天、王大陆搏命黑吃黑！横跨黑白两道只手遮天的洪泰集团正值换选之际，一个神秘杀手陈安（张家辉 饰）却突然只身闯入这个是非混乱的旋涡，搅得洪泰集团大乱。身处警察阵营的麦朗汶（阮经天 饰）和黑帮阵营的马文康（王大陆 饰）也盯上了他……各方势力伺机而动，谁才是幕后的操控者？一场生猛混战一触即发。"
            },
            role: [],
            pic: []
        }
    }, methods: {
        getmovie() {
            this.$axios({
                method: 'get',
                url: '/app/movie/' + this.$route.query.id,
            }).then((result) => {
                this.movie = result.data.data
                this.score = result.data.data.score / 2
            }).catch((err) => {

            })
        },
        getactor() {
            this.$axios({
                method: 'get',
                url: '/app/actor-movie/detail/' + this.$route.query.id,
            }).then((result) => {
                console.log(result);
                result.data.data.forEach(e => {

                    if (this.role.length < 5) {

                        this.role.push({ actor: e.actor, character: e.character })
                    }
                })

            }).catch((err) => {

            });
        },
        getpic() {
            this.$axios({
                method: 'get',
                url: '/app/movie-img/imgs/' + this.$route.query.id,
            }).then((result) => {
                console.log(result);
                result.data.data.forEach(e => {

                    if (this.pic.length < 5) {

                        this.pic.push(e)
                    }
                })

            }).catch((err) => {

            });
        }
    },
    computed: {
        smillpic() {
            // 使用slice方法截取从第二个元素开始的子数组
            return this.pic.slice(1);
        },
        bigpic() {
            return this.pic.slice(0, 1);
        },
        showtime: () => {

            return (time) => {
                console.log(time);
                 return parseInt(time/60)+'小时'+parseInt(time%60)+'分钟'
                
            }
        }
    },
    mounted() {
        this.getmovie()
        this.getactor()
        this.getpic()



    }


}
</script>
